//! The record store (design §3): the ONLY writer of the app's records. Rust does the file work; the encryption is the
//! platform's (Kotlin Keystore AES-GCM, IV generated by the Keystore and stored with the ciphertext), so this module
//! handles opaque sealed bytes and gives the caller the AAD to seal / open with.
//! - Write: temp file in the same directory -> `sync_all` -> rename over the final name -> `sync_all` on the directory.
//!   A crash leaves the old record or the new one, never half of one; a left-over temp file is never read and is
//!   removed by `sweep_temps`.
//! - Format: "BMR" ‖ version (1) ‖ generation (u64 BE) ‖ sealed. An unknown version is neither read nor overwritten.
//! - AAD = "batman-record-v1\0" ‖ final relative path ‖ "\0" ‖ generation (u64 BE): a record moved to another path, or
//!   with its header generation changed, does not open. ⚠️ Putting back an OLDER copy of the same file (rollback) still
//!   opens: detecting it needs a counter kept elsewhere; only someone who can write the app-private directory (root)
//!   can do it, and they can call the keys directly — recorded as a gap, no mechanism added.

use std::fs::{self, File, OpenOptions};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

pub const VERSION: u8 = 1;
const MAGIC: &[u8; 3] = b"BMR";
const HEADER: usize = 3 + 1 + 8;
const TEMP_MARK: &str = ".tmp-";

#[derive(Debug)]
pub enum Error {
    BadPath,
    UnknownVersion(u8),
    NotARecord,
    Io(std::io::Error),
    Random,
    /// write_cas: the record's generation on disk is not the one it was read at (written elsewhere since)
    Stale { expected: u64, found: u64 },
}

/// write_cas's read-compare-write runs under this one process-wide lock (join2 design §3.1).
static CAS: std::sync::Mutex<()> = std::sync::Mutex::new(());

impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Self {
        Error::Io(e)
    }
}

/// Relative record paths: `kind/name`, lowercase ASCII letters, digits, `-` and `_` only (device ids are hex, net ids
/// hex): no `..`, no absolute path, no hidden or temp names.
pub fn valid_path(rel: &str) -> bool {
    let parts: Vec<&str> = rel.split('/').collect();
    parts.len() == 2
        && parts.iter().all(|p| !p.is_empty() && p.len() <= 64 && p.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-' || b == b'_'))
}

pub fn aad(rel: &str, generation: u64) -> Vec<u8> {
    let mut a = b"batman-record-v1\0".to_vec();
    a.extend(rel.as_bytes());
    a.push(0);
    a.extend(generation.to_be_bytes());
    a
}

pub struct Store {
    root: PathBuf,
}

/// What a read returns: the generation from the header and the sealed bytes to open with `aad(rel, generation)`.
#[derive(Debug, PartialEq, Eq)]
pub struct Sealed {
    pub generation: u64,
    pub sealed: Vec<u8>,
}

impl Store {
    pub fn new(root: impl Into<PathBuf>) -> Store {
        Store { root: root.into() }
    }

    fn path(&self, rel: &str) -> Result<PathBuf, Error> {
        if !valid_path(rel) {
            return Err(Error::BadPath);
        }
        Ok(self.root.join(rel))
    }

    pub fn read(&self, rel: &str) -> Result<Option<Sealed>, Error> {
        let p = self.path(rel)?;
        let mut b = Vec::new();
        match File::open(&p) {
            Ok(mut f) => f.read_to_end(&mut b)?,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(e) => return Err(e.into()),
        };
        if b.len() < HEADER || &b[..3] != MAGIC {
            return Err(Error::NotARecord);
        }
        if b[3] != VERSION {
            return Err(Error::UnknownVersion(b[3]));
        }
        let generation = u64::from_be_bytes(b[4..12].try_into().expect("8 bytes"));
        Ok(Some(Sealed { generation, sealed: b[HEADER..].to_vec() }))
    }

    /// The generation the next write of `rel` must use (and seal with): current + 1, or 1 for a new record. An existing
    /// record of an unknown version stops here (never overwritten).
    pub fn next_generation(&self, rel: &str) -> Result<u64, Error> {
        Ok(self.read(rel)?.map_or(1, |s| s.generation + 1))
    }

    /// Atomically replace `rel` with `sealed` (sealed by the caller with `aad(rel, generation)`).
    pub fn write(&self, rel: &str, generation: u64, sealed: &[u8]) -> Result<(), Error> {
        let p = self.path(rel)?;
        match self.read(rel) {
            Err(Error::UnknownVersion(v)) => return Err(Error::UnknownVersion(v)),
            Err(Error::NotARecord) => return Err(Error::NotARecord),
            _ => {}
        }
        let dir = p.parent().ok_or(Error::BadPath)?;
        fs::create_dir_all(dir)?;
        let mut rnd = [0u8; 8];
        getrandom::fill(&mut rnd).map_err(|_| Error::Random)?;
        let name = p.file_name().and_then(|n| n.to_str()).ok_or(Error::BadPath)?;
        let tmp = dir.join(format!(".{name}{TEMP_MARK}{}", crate::nodecert::hex_lower(&rnd)));
        {
            let mut f = OpenOptions::new().write(true).create_new(true).open(&tmp)?;
            f.write_all(MAGIC)?;
            f.write_all(&[VERSION])?;
            f.write_all(&generation.to_be_bytes())?;
            f.write_all(sealed)?;
            f.sync_all()?;
        }
        fs::rename(&tmp, &p)?;
        File::open(dir)?.sync_all()?;
        Ok(())
    }

    /// Compare-and-swap write (join2 design §3.1): only when the header generation on disk is `expected_gen` (0 = no
    /// record yet), `rel` is replaced with `sealed` at generation `expected_gen + 1` — the generation the caller sealed
    /// with (`aad(rel, expected_gen + 1)`). `expected_gen` is the generation the record was READ at, never re-read
    /// here: a write elsewhere in between is `Stale` and nothing is written. Returns the new generation.
    pub fn write_cas(&self, rel: &str, expected_gen: u64, sealed: &[u8]) -> Result<u64, Error> {
        let _g = CAS.lock().unwrap_or_else(|p| p.into_inner());
        let found = self.read(rel)?.map_or(0, |s| s.generation);
        if found != expected_gen {
            return Err(Error::Stale { expected: expected_gen, found });
        }
        let g = expected_gen + 1;
        self.write(rel, g, sealed)?;
        Ok(g)
    }

    /// Remove `rel` (e.g. a claim-pending turned into a node record, or forgotten by the user) and sync the directory.
    pub fn remove(&self, rel: &str) -> Result<(), Error> {
        let p = self.path(rel)?;
        match fs::remove_file(&p) {
            Ok(()) => {}
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(e) => return Err(e.into()),
        }
        if let Some(d) = p.parent() {
            File::open(d)?.sync_all()?;
        }
        Ok(())
    }

    /// Keep a copy of `rel` (design 254-app-claim-noover R8): its whole file (header, generation, sealed bytes) goes
    /// to a temp file in `<kind>/`, synced, then renamed to the first free `<kind>/<name>-<n>` (n = 1, 2, ...; free =
    /// `symlink_metadata` says NotFound, so a dangling symlink is taken; any other error stops), then the directory is
    /// synced. `rel` is never changed. The copy opens only once moved back to `rel` (the AAD is bound to it). Returns
    /// the copy's path, or None when there is no record at `rel`; a file that is not a record is not copied. Runs under
    /// the CAS lock: bridge calls come from a thread pool, and two copies must never pick the same name.
    pub fn copy_aside(&self, rel: &str, kind: &str) -> Result<Option<String>, Error> {
        let _g = CAS.lock().unwrap_or_else(|p| p.into_inner());
        let from = self.path(rel)?;
        if self.read(rel)?.is_none() {
            return Ok(None);
        }
        let bytes = fs::read(&from)?;
        let name = rel.rsplit('/').next().ok_or(Error::BadPath)?;
        let dir = self.path(&format!("{kind}/{name}-1"))?.parent().ok_or(Error::BadPath)?.to_path_buf();
        fs::create_dir_all(&dir)?;
        let mut rnd = [0u8; 8];
        getrandom::fill(&mut rnd).map_err(|_| Error::Random)?;
        let tmp = dir.join(format!(".{name}{TEMP_MARK}{}", crate::nodecert::hex_lower(&rnd)));
        {
            let mut f = OpenOptions::new().write(true).create_new(true).open(&tmp)?;
            f.write_all(&bytes)?;
            f.sync_all()?;
        }
        let r = (|| {
            for n in 1u32.. {
                let to_rel = format!("{kind}/{name}-{n}");
                let to = self.path(&to_rel)?;
                match fs::symlink_metadata(&to) {
                    Ok(_) => continue,
                    Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                    Err(e) => return Err(e.into()),
                }
                #[cfg(test)]
                test_gap();
                fs::rename(&tmp, &to)?;
                File::open(&dir)?.sync_all()?;
                return Ok(Some(to_rel));
            }
            unreachable!("u32 names run out")
        })();
        if r.is_err() {
            let _ = fs::remove_file(&tmp);
        }
        r
    }

    /// Delete temp files left by a crash in the middle of a write (never valid records). Returns how many.
    pub fn sweep_temps(&self) -> Result<usize, Error> {
        let mut n = 0;
        let Ok(kinds) = fs::read_dir(&self.root) else { return Ok(0) };
        for k in kinds.flatten() {
            if !k.file_type()?.is_dir() {
                continue;
            }
            for f in fs::read_dir(k.path())?.flatten() {
                let name = f.file_name();
                if name.to_str().is_some_and(|s| s.starts_with('.') && s.contains(TEMP_MARK)) {
                    fs::remove_file(f.path())?;
                    n += 1;
                }
            }
        }
        Ok(n)
    }

    pub fn root(&self) -> &Path {
        &self.root
    }
}

/// Tests only: a pause between copy_aside's free-name check and its rename, to widen the window T13 races in.
#[cfg(test)]
static GAP_MS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

#[cfg(test)]
fn test_gap() {
    let ms = GAP_MS.load(std::sync::atomic::Ordering::SeqCst);
    if ms > 0 {
        std::thread::sleep(std::time::Duration::from_millis(ms));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // design 254-app-claim-noover T13: two threads keep a copy of the same record at once -> two distinct copies (the
    // CAS lock serialises the free-name check and the rename; without it both take -1 and one copy is lost).
    #[test]
    fn t13_concurrent_copies_never_share_a_name() {
        let root = std::env::temp_dir().join(format!("bp-store-t13-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        Store::new(&root).write("node/e61551410cfd538e24", 4, b"rec").unwrap();
        GAP_MS.store(300, std::sync::atomic::Ordering::SeqCst);
        let hs: Vec<_> = (0..2)
            .map(|_| {
                let r = root.clone();
                std::thread::spawn(move || Store::new(r).copy_aside("node/e61551410cfd538e24", "forgotten-node").unwrap())
            })
            .collect();
        let mut got: Vec<String> = hs.into_iter().map(|h| h.join().unwrap().unwrap()).collect();
        GAP_MS.store(0, std::sync::atomic::Ordering::SeqCst);
        got.sort();
        assert_eq!(got, ["forgotten-node/e61551410cfd538e24-1", "forgotten-node/e61551410cfd538e24-2"]);
        let names: Vec<_> = fs::read_dir(root.join("forgotten-node")).unwrap().map(|e| e.unwrap().file_name()).collect();
        assert_eq!(names.len(), 2, "both copies on disk, no temp left: {names:?}");
        let _ = fs::remove_dir_all(root);
    }
}
